// ModelXD Playground (owner, Sep 14): an image-led create/remix gallery.
// Four finished artworks and two text scenario presets, in the site's five
// languages. Every item carries an image prompt and a separate, concise
// motion prompt; the page prefills XDuel (image duel) and XDirect (film)
// with them and never runs anything.
//
// Provenance: the vampire artwork is an original character generated by
// Codex with its built-in image generation (playground-assets/manifest.json,
// 2026-09-14, "Not a ModelXD generation or duel result"). The three game
// works are unofficial fan concepts from the same tool
// (game-gallery-assets/manifest.json). No item is an XDuel result; no model
// name, price or vote is attached.
//
// Prompts: `sourcePrompt` is the exact English prompt the picture was made
// from, kept verbatim and shown on demand. `imagePrompt` holds the editable
// display defaults per language: English is the source verbatim; the other
// four are translations written for this page (not new generations), and
// they leave out the source's "for a Japanese game-show website" asset note.
// Motion prompts and the presets were written for this page in all five
// languages. image = the supplied 1672x941 PNG (lightbox); thumb = a JPEG
// copy of the same file for cards and the home hero.
export type Lang5 = 'en' | 'zh-Hant' | 'zh-Hans' | 'ja' | 'ko'
export type Localized = Record<Lang5, string>
export type PgArtwork = {
  kind: 'artwork'
  original: boolean          // false = unofficial fan art of a named game
  slug: string
  image: string
  thumb: string
  title: Localized
  reference: Localized
  alt: Localized
  sourcePrompt: string       // manifest prompt, verbatim (English)
  imagePrompt: Localized     // editable display default per language
  videoPrompt: Localized
}
export type PgPreset = {
  kind: 'preset'
  slug: string
  emoji: string
  title: Localized
  blurb: Localized
  imagePrompt: Localized
  videoPrompt: Localized
}
export type PgItem = PgArtwork | PgPreset

